// =============================================================================
//  LocalizationCS.cpp  -- The Hell 4 -- Czech overlay  (th4)
//  LANG_CS = 20. Latin script, REAL CP1250 DIACRITICS (the Polish model).
//
//  Written by a one-off generator (2026-10-06) from UTF-8 translation data that is NOT part
//  of the source tree. From now on this file IS the source: edit it by hand like any other
//  Localization<XX>.cpp, following the encoding rules below. Translated by machine (Claude)
//  with the Polish loc as the grammatical reference; no native review yet -- fixes from
//  Czech players are expected.
//
//  ---- ENCODING ------------------------------------------------------------
//  * Byte encoding is CP1250 (Central European, same as Polish). Read/write this file
//    in Python with encoding='cp1250' or 'latin-1' for raw bytes; NEVER 'utf-8'.
//  * Czech letters are \xNN escapes so the file stays ASCII:
//      A-acute \xC1  C-caron \xC8  D-caron \xCF  E-acute \xC9  E-caron \xCC  I-acute \xCD
//      N-caron \xD2  O-acute \xD3  R-caron \xD8  S-caron \x9A* T-caron \x8D  U-acute \xDA
//      U-ring  \xD9  Y-acute \xDD  Z-caron \x8E
//      lowercase: \xE1 \xE8 \xEF \xE9 \xEC \xED \xF2 \xF3 \xF8 \x9A \x9D \xFA \xF9 \xFD \x9E
//      * S-caron is the lowercase byte \x9A in every table but CS_Menu: the capital \x8A sits inside the colour-control
//        window 0x80..0x8B (Tooltip.cpp IsColorControlByte). The caps-only fonts draw both the same.
//  * *** THE GREEDY-HEX C2022 TRAP APPLIES *** (as in RU/PT/FR/PL): a \x escape eats
//    every following ASCII hex digit INCLUDING a-f / A-F: write "\xE8""ek", never the
//    escape directly followed by "ek" (that fuses into one too-big char).
//    Check with regex  \\x[0-9A-Fa-f]{2}[0-9A-Fa-f]  -> must be 0 hits.
//  * The in-game CEL fonts are CAPS-ONLY; lowercase bytes alias the uppercase glyph.
//  * CS_Menu is drawn ONLY by the META-MENU atlas (ui_art font16/24/30/42, raw bytes, no
//    colour codes). TH4loc_cze.mor ships that atlas with the Czech cells at their CP1250
//    positions, so CS_Menu has full diacritics and is the one table that may use the real
//    capital S-caron 0x8A. The trait texts are drawn by BOTH fonts (character creation and
//    the in-game perk tooltip, Perks.cpp), so they follow the in-game rule: S-caron = 0x9A.
//  * Keys must byte-exactly match the English source literal.
//
//  ---- FONTS ---------------------------------------------------------------
//  TH4loc_cze.mor (mounted at 8900 only when language == CS, Windows.cpp) ships the
//  three CEL fonts with the 15 Czech capitals. Tables: Codepage_Czech / FontIndex*_Czech /
//  FontWidth{Mid,Big}_Czech in dataseg.cpp; FontWidthSmall[94..108] appended.
//  The pack and those tables are a matched pair (see dataseg.cpp).
//
//  ---- GRAMMAR CONVENTIONS (keep consistent) --------------------------------
//  * Plural triples follow Czech: _one = 1, _few = 2-4, _many = 0 and 5+ (incl. 21, 22 --
//    unlike Polish, Czech has no "22 -> few"). See the charges line in Panel.cpp.
//  * Griswold's possessive is always the GENITIVE "Griswolda" (never "Griswolduv"), so the
//    Dark Campaign rename (Localization.cpp DarkCampaignRenameSmith) can swap it for
//    "Hephasta".
//
//  English source is inviolable -- translate via these overlays only.
// =============================================================================
#include "stdafx.h"

struct UiStr  { const char* en; const char* cs; }; // .cs column holds the Czech text
struct IdxStr { int index; const char* tr; };

// MUST stay in sync with the master enum in Localization.cpp -- the ids are array
// indices shared across translation units.
enum {
	OVL_UI = 0, OVL_MENU, OVL_UNIQUE_ITEM, OVL_AFFIX_PREFIX, OVL_AFFIX_SUFFIX,
	OVL_BASE_ITEM, OVL_BASE_NAME2, OVL_ELEMENT, OVL_SPICIES, OVL_ICEAGE,
	OVL_SPELL, OVL_SPELL_NOM, OVL_PERK_NAME, OVL_PERK_DESC, OVL_WARP,
	OVL_WARP_OBL,
	OVL_STR_COUNT
};
enum { OVL_SPEECH = 0, OVL_ONSCREEN, OVL_QUEST, OVL_IDX_COUNT };

// A lone placeholder row ({ 0, 0 } / { -1, 0 }) counts as 0 rows => English fallback.
static bool isPlaceholder( const UiStr&  r ) { return r.en == 0; }
static bool isPlaceholder( const IdxStr& r ) { return r.index < 0 && r.tr == 0; }

template<typename T, size_t N>
static int countRows( const T (&arr)[N] )
{
	if( N == 1 && isPlaceholder( arr[0] ) ) return 0;
	return (int)N;
}

