const UiStr* CS_GetStrTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_UI:           *n = countRows( CS_Ui ); return CS_Ui;
		case OVL_MENU:         *n = countRows( CS_Menu ); return CS_Menu;
		case OVL_UNIQUE_ITEM:  *n = countRows( CS_UniqueItem ); return CS_UniqueItem;
		case OVL_AFFIX_PREFIX: *n = countRows( CS_AffixPrefix ); return CS_AffixPrefix;
		case OVL_AFFIX_SUFFIX: *n = countRows( CS_AffixSuffix ); return CS_AffixSuffix;
		case OVL_BASE_ITEM:    *n = countRows( CS_BaseItem ); return CS_BaseItem;
		case OVL_BASE_NAME2:   *n = countRows( CS_BaseName2 ); return CS_BaseName2;
		case OVL_ELEMENT:      *n = countRows( CS_Element ); return CS_Element;
		case OVL_SPICIES:      *n = countRows( CS_Spicies ); return CS_Spicies;
		case OVL_ICEAGE:       *n = countRows( CS_IceAge ); return CS_IceAge;
		case OVL_SPELL:        *n = countRows( CS_Spell ); return CS_Spell;
		case OVL_SPELL_NOM:    *n = countRows( CS_SpellNom ); return CS_SpellNom;
		case OVL_PERK_NAME:    *n = countRows( CS_PerkName ); return CS_PerkName;
		case OVL_PERK_DESC:    *n = countRows( CS_PerkDesc ); return CS_PerkDesc;
		case OVL_WARP:         *n = countRows( CS_Warp ); return CS_Warp;
		case OVL_WARP_OBL:     *n = countRows( CS_WarpOblique ); return CS_WarpOblique;
	}
	*n = 0; return 0;
}

const IdxStr* CS_GetIdxTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_SPEECH:   *n = countRows( CS_Speech ); return CS_Speech;
		case OVL_ONSCREEN: *n = countRows( CS_OnScreen ); return CS_OnScreen;
		case OVL_QUEST:    *n = countRows( CS_Quest ); return CS_Quest;
	}
	*n = 0; return 0;
}

