// CS_GCInfoDesc
const char* CS_GCInfoDesc( int gc )
{
	switch( gc ){
		case 0: return "Nic (vynech\xE1no)";
		case 1: return "Automatick\xE9 ukl\xE1""d\xE1n\xED\n\n\nM\xECn\xED styl hry\n\nHr\xE1\xE8 nemus\xED ukl\xE1""dat hru ru\xE8n\xEC, ukl\xE1""d\xE1 se automaticky, stejn\xEC jako v re\x9Eimu v\xED""ce hr\xE1\xE8\xF9.";
		case 2: return "V\xE1zan\xE1 v\xFDstroj\n\n\nP\xF8id\xE1v\xE1 v\xFDzvu\n\nZnemo\x9E\xF2uje nasazovat a odkl\xE1""dat p\xF8""edm\xECty v boji (krom\xEC slot\xF9 rukou).";
		case 3: return "Ztr\xE1ta p\xF8""edm\xECt\xF9\n\n\nP\xF8id\xE1v\xE1 v\xFDzvu\n\nPo smrti upust\xED\x9A nasazen\xE9 p\xF8""edm\xECty.\n\nPozor: pokud upu\x9At\xECn\xE9 p\xF8""edm\xECty nez\xEDsk\xE1\x9A zp\xECt ve stejn\xE9 hern\xED relaci, zmiz\xED.";
		case 4: return "Bez n\xE1mahy\n\n\nUsnad\xF2uje hru\n\nNetvo\xF8i ti zp\xF9sobuj\xED jen polovi\xE8n\xED po\x9Akozen\xED.\nSnaz\x9A\xED u\x9E to nebude.";
		case 5: return "Ze zem\xEC\n\n\nP\xF8id\xE1v\xE1 v\xFDzvu\n\nM\xEC\x9A\x9D""an\xE9 ti neprodaj\xED \x9E\xE1""dn\xE9 p\xF8""edm\xECty.\n\nSv\xE9 slu\x9E""by ti ale poskytovat nep\xF8""estanou: drby, rozhovory k \xFAkol\xF9m, opravy, identifikace, o\xE8""arov\xE1n\xED, v\xFDroba, osazov\xE1n\xED obj\xEDmek, dob\xEDjen\xED.";
		case 6: return "Nemo\x9En\xE9\n\n\nZt\xEC\x9Euje hru\n\nNetvo\xF8i ti zp\xF9sobuj\xED dvojit\xE9 po\x9Akozen\xED.\nT\xEC\x9E\x9A\xED u\x9E to nebude.";
		case 7: return "Prohibice\n\n\nP\xF8id\xE1v\xE1 v\xFDzvu\n\nNetvo\xF8i u\x9E nebudou n\xE1hodn\xEC upou\x9At\xECt elix\xEDry atribut\xF9\nPozn\xE1mka: schopnost Velk\xFD pijan d\xE1l d\xE1v\xE1 elix\xEDry z unik\xE1tn\xED""ch netvor\xF9";
		case 8: return "Pln\xFD kontakt\n\n\nUsnad\xF2uje hru\n\nNetvo\xF8i s \xFAtoky na d\xE1lku neustupuj\xED.";
		case 9: return "No\xE8n\xED rod\n\n\nD\xECl\xE1 z tebe up\xEDra\n\n\x8Eije\x9A a um\xEDr\xE1\x9A krv\xED. Tv\xF9j hlad je neukojiteln\xFD, ale m\xE1\x9A v\x9A""echny n\xE1stroje k lovu slab\xFD""ch\n\nM\xECn\xED to hratelnost.\nNepou\x9E\xEDv\xE1\x9A p\xF8""edm\xECty a spol\xE9h\xE1\x9A na sv\xE9 vrozen\xE9 s\xEDly.";
		case 10: return "Sekat a bodat\n\n\nUsnad\xF2uje hru\n\nU\x9E nemus\xED\x9A m\xECnit typ zbran\xEC (ostr\xE1 nebo tup\xE1) podle typu netvora. V\x9A""echny zbran\xEC zp\xF9sobuj\xED standardn\xED po\x9Akozen\xED v\x9A""em druh\xF9m netvor\xF9.";
		case 11: return "O\xE8kovan\xFD\n\n\nUsnad\xF2uje hru\n\nNetvo\xF8i ztr\xE1""cej\xED v\x9A""echny imunity a nen\xED t\xF8""eba m\xECnit kouzla - funguje ka\x9E""d\xFD typ kouzla.\nNet\xFDk\xE1 se Kamenn\xE9 kletby, Ducha kost\xED, \x9Eiveln\xFD""ch a svat\xFD""ch kouzel.";
		case 12: return "To je moje tajemstv\xED\n\n\nUsnad\xF2uje hru\n\nZu\xF8ivost nem\xE1 dobu obnovy a lze ji seslat znovu, jakmile skon\xE8\xED.";
		case 13: return "Bez regenerace\n\n\nP\xF8id\xE1v\xE1 v\xFDzvu\n\nPostava nem\xE1 z\xE1kladn\xED regeneraci \x9Eivota a many.";
		case 14: return "\xC8ist\xE9 ruce\n\n\nP\xF8id\xE1v\xE1 v\xFDzvu\n\nNetvo\xF8i neupou\x9At\xECj\xED p\xF8""edm\xECty, kter\xE9 m\xF9\x9E""e postava nasadit.\nHr\xE1\xE8 je m\xE1 z\xEDskat n\xE1kupem a/nebo o\xE8""arov\xE1n\xEDm.";
		case 15: return "Doba ledov\xE1\n\n\nKosmetick\xE1 zm\xECna\n\n\xDArovn\xEC kobky vypadaj\xED jako v hlubok\xE9, hlubok\xE9 zim\xEC, v\x9A""e je zledovat\xECl\xE9 a zmrzl\xE9.\nP\xF8""edstavoval sis n\xECkdy, jak by vypadalo zamrzl\xE9 Peklo?";
		case 16: return "Na Hromnice\n\n\nM\xECn\xED styl hry\n\nPoka\x9E""d\xE9 se vygeneruje stejn\xE1 kobka se stejn\xFDmi netvory. M\xF9\x9E""e\x9A hr\xE1t a p\xF8i ka\x9E""d\xE9 h\xF8""e zlep\x9Aovat sv\xE9 \xE8""asy.";
		case 17: return "Odoln\xECj\x9A\xED netvo\xF8i\n\n\nZt\xEC\x9Euje hru\n\nNetvo\xF8i maj\xED +200% \x9Eivot\xF9.";
		case 18: return "Nezni\xE8iteln\xE9 p\xF8""edm\xECty\n\n\nUsnad\xF2uje hru\n\nP\xF8""edm\xECty se nezni\xE8\xED, kdy\x9E v\xFD""dr\x9E klesne na nulu. M\xEDsto toho budou nepou\x9Eiteln\xE9 a\x9E do opravy.";
		case 19: return "Bez mapy\n\n\nP\xF8id\xE1v\xE1 v\xFDzvu\n\nAutomapa nen\xED k dispozici\nCestu kobkami bude\x9A muset naj\xEDt, ani\x9E by ses na ni spol\xE9hal\n\nU\x9E se c\xEDt\xED\x9A ztracen?";
		case 20: return "Dvojit\xE9 po\x9Akozen\xED\n\n\nUsnad\xF2uje hru\n\nTv\xE9 \xFAtoky zp\xF9sobuj\xED netvor\xF9m dvojit\xE9 po\x9Akozen\xED\n\nPozor: hra m\xF9\x9E""e b\xFDt a\x9E nudn\xEC snadn\xE1.\nNevyb\xEDrej, pokud si chce\x9A zachovat nap\xECt\xED boje.";
		case 21: return "Nevid\xEDm zlo\n\n\nP\xF8id\xE1v\xE1 v\xFDzvu\n\nVid\xECn\xED nezv\xFDraz\xF2uje netvory ve tm\xEC.";
		case 22: return "\xC8""ern\xE1 smrt\n\n\nJsi naka\x9E""en\n\nZmocnil se t\xEC mor \xC8""ern\xE9 smrti. Pomalu se u tebe rozvinou nep\xF8\xEDzniv\xE9 p\xF8\xEDznaky, kter\xE9 t\xEC nakonec nevyhnuteln\xEC zabij\xED.\n\nNem\xF9\x9E""e\x9A ho vyl\xE9\xE8it, nem\xF9\x9E""e\x9A ho zahojit a nem\xF9\x9E""e\x9A ho zastavit. \xC8""asem bude st\xE1le hor\x9A\xED. P\xF8""ed touto smrtelnou nemoc\xED nen\xED \xFAniku.";
		case 23: return "Sm\xF9la\n\n\nP\xF8id\xE1v\xE1 v\xFDzvu\n\n\x9At\xECst\xED d\xF8\xEDv nebo pozd\xECji dojde. Tvoje ani neza\xE8""alo.\n\nZa\xE8\xEDn\xE1\x9A se v\x9A""emi atributy rovn\xFDmi 5. Za \xFArove\xF2 dostane\x9A jen 2 body atribut\xF9. Hled\xE1n\xED magie, z\xEDskan\xE9 zku\x9A""enosti a nal\xE9z\xE1n\xED zlata sn\xED\x9E""eny o 75%. Za\xE8\xEDn\xE1\x9A hru bez p\xF8""edm\xECt\xF9.\n\n\x8E\xE1""dn\xE9 schopnosti, kter\xE9 by ti pomohly se zku\x9A""enostmi, elix\xEDry, hled\xE1n\xEDm magick\xFD""ch p\xF8""edm\xECt\xF9 a atributy za \xFArove\xF2.";
		case 24: return "Nel\xEDtostn\xE9 \x9E""elezo\n\n\nP\xF8id\xE1v\xE1 v\xFDzvu\n\nKlasick\xFD Ironman v Diablu byl jin\xFD.\n\nNebyly bonusy k atribut\xF9m za \xFArove\xF2, \x9E\xE1""dn\xE9 zku\x9A""enosti nav\xED""c, \x9E\xE1""dn\xE9 oleje ani identifikace od boss\xF9. Ani zlep\x9A""en\xED MF.\n\nTento modifik\xE1tor t\xEC vrac\xED ke ko\xF8""en\xF9m.";
		case 25: return "Zrychlen\xED\n\n\nUsnad\xF2uje hru\n\nZku\x9A""enosti zv\xFD\x9A""eny 2x.";
		case 26: return "Askeze\n\n\nP\xF8id\xE1v\xE1 v\xFDzvu\n\nHra se ukl\xE1""d\xE1 automaticky.\n\nPo smrti upust\xED\x9A p\xF8""edm\xECty. Ve m\xECst\xEC nelze o\x9Eivnout (mus\xED\x9A zalo\x9Eit novou hru), a proto p\xF8ijde\x9A o v\x9A""echny upu\x9At\xECn\xE9 p\xF8""edm\xECty.\n\nJe to jako re\x9Eim Hardcore, ale m\xEDsto postavy ztrat\xED\x9A nasazen\xE9 p\xF8""edm\xECty.";
		case 27: return "Termin\xE1tor\n\n\nJsi jednotka s\xE9rie Cyberdyne Systems. Model 101, infiltr\xE1tor. Re\x9Eim \xE8ten\xED-z\xE1pis CPU aktivov\xE1n. Posl\xE1n do minulosti splnit misi.\n\nHlavn\xED c\xEDl: Uber Diablo.\n\nVedlej\x9A\xED c\xEDl: vyhladit netvory.\n\nPodm\xEDnka: p\xF9sobit na m\xEDstn\xED subjekty jako \xE8lov\xECk.\n\nZ\xE1kladn\xED vylep\x9A""en\xED nainstalov\xE1na. Dal\x9A\xED vylep\x9A""en\xED dostupn\xE1 samou\xE8""en\xEDm.";
		case 28: return "Supermutant\n\n\nTv\xE9 t\xEClo unese zbran\xEC, kter\xE9 by zlomily norm\xE1ln\xEDho mu\x9E""e vp\xF9li.\n\nMiniguny.\n\nV\xEC""ci, kter\xE9 by na tomto sv\xECt\xEC nem\xECly existovat. U\x9E neses\xEDl\xE1\x9A kouzla. Nepot\xF8""ebuje\x9A.\n\nKdy\x9E stiskne\x9A spou\x9A\x9D, d\xE1vka trh\xE1 pekeln\xE9 zplozence jako pap\xEDr v bou\xF8i.";
		case 29: return "Voj\xE1k Enkl\xE1vy\n\n\nVoj\xE1k Ozbrojen\xFD""ch sil Enkl\xE1vy, vycvi\xE8""en\xFD vyhlazovat mutanty a genetickou ne\xE8istotu.\n\nOcit\xE1 se ve sv\xECt\xEC, kter\xFD nikdy nepoznal jadern\xFD ohe\xF2, ale m\xE1 \x9Ap\xEDnu jin\xE9ho druhu - pekeln\xE9 zplozence.\n\nNep\xF8\xEDtel se zm\xECnil. \xDA\xE8""el ne.\n\nDovednosti: Ovl\xE1""d\xE1 energetick\xE9 zbran\xEC a nasazuje bojov\xE9 drony. Zb\xEChl\xFD v \x9Eiveln\xE9m boji.";
		default: return nullptr;
	}
}

